use std::io::{self, BufWriter, Write};
fn write_lines<W: Write>(out: &mut W, lines: &[&str]) -> io::Result<()> {
    for line in lines {
        out.write_all(line.as_bytes())?;
        out.write_all(b"\n")?;
    }
    Ok(())
}
fn main() -> io::Result<()> {
    let lines = ["one", "two"];
    let mut direct = Vec::new();
    write_lines(&mut direct, &lines)?;
    let mut buffered = BufWriter::with_capacity(64, Vec::new());
    write_lines(&mut buffered, &lines)?;
    buffered.flush()?;
    assert_eq!(&direct, buffered.get_ref());
    println!("Both writers produced the same bytes");
    Ok(())
}

